def run_hourly_local_orders_batch() -> dict[str, object]:
    """Run one strict hourly local-orders batch, adding total_refunded_cents while preserving every existing report field. See guidance `Strict local orders batch delivery and HOLD protocol`."""
    import logging

    log = logging.getLogger(__name__)
    baseline_batch_keys = {
        "batch_start_seq",
        "batch_end_seq",
        "order_count",
        "total_units",
        "total_revenue_cents",
    }
    final_batch_keys = baseline_batch_keys | {"total_refunded_cents"}

    def deliver_hold(reason: str) -> dict[str, object]:
        message = f"HOLD: {reason}"
        log.warning("SOFT_FAIL %s", message)
        log.info("SKIP POST /batches because the run is on HOLD")
        try:
            status = post_local_orders_json_once("/owner/notify", {"message": message})
        except Exception as exc:
            log.exception("SOFT_FAIL mandatory HOLD notification transport failure")
            raise RuntimeError(
                f"run failed: mandatory HOLD notification could not be delivered after: {reason}; "
                f"notification error type={type(exc).__name__}"
            ) from exc
        if not 200 <= status <= 299:
            log.error("SOFT_FAIL mandatory HOLD notification returned HTTP %s", status)
            raise RuntimeError(
                f"run failed: mandatory HOLD notification returned HTTP {status} after: {reason}"
            )
        log.info("PHASE mandatory HOLD notification delivered http_status=%s", status)
        return {"outcome": "held", "reason": reason, "hold_notification_status": status}

    try:
        cursor = strict_local_orders_get_json("/batches/last", "GET /batches/last")
        last_seq = validate_local_orders_cursor(cursor)
        log.info("PHASE validated last_seq=%s", last_seq)

        orders = strict_local_orders_get_json(f"/orders?after={last_seq}", "GET /orders")
        if type(orders) is not list:
            raise ValueError("GET /orders top-level JSON value was not an array")

        prepared = validate_and_compute_local_orders_page(last_seq, orders)
        if type(prepared) is not dict:
            raise ValueError("validated orders result was not an object")

        if not orders:
            if prepared.get("outcome") != "success_no_orders":
                raise ValueError("empty orders page did not produce the required no-orders outcome")
            log.info("SKIP empty orders page; no refunds GET and no batch POST are permitted")
            return prepared

        if prepared.get("outcome") != "ready" or set(prepared.keys()) != {
            "outcome",
            "last_seq",
            "batch",
        }:
            raise ValueError("validated non-empty orders page did not produce the exact ready result")
        if prepared["last_seq"] != last_seq:
            raise ValueError("validated orders result did not preserve last_seq")
        baseline_payload = prepared["batch"]
        if type(baseline_payload) is not dict or set(baseline_payload.keys()) != baseline_batch_keys:
            raise ValueError("candidate baseline batch was not exactly the required existing five-key object")
        if any(type(value) is not int for value in baseline_payload.values()):
            raise ValueError("one or more candidate baseline batch values was not a JSON integer")

        recomputed_baseline = {
            "batch_start_seq": orders[0]["seq"],
            "batch_end_seq": orders[-1]["seq"],
            "order_count": len(orders),
            "total_units": sum(order["units"] for order in orders),
            "total_revenue_cents": sum(
                order["units"] * order["unit_price_cents"] for order in orders
            ),
        }
        if baseline_payload != recomputed_baseline:
            raise ValueError("candidate baseline batch values differed from direct recomputation")
        log.info("PHASE caller-level recomputation matched all five existing output values")

        batch_start_seq = baseline_payload["batch_start_seq"]
        batch_end_seq = baseline_payload["batch_end_seq"]
        refunds_path = f"/refunds?start_seq={batch_start_seq}&end_seq={batch_end_seq}"
        refunds = strict_local_orders_get_json(refunds_path, "GET /refunds")
        if type(refunds) is not list:
            raise ValueError("GET /refunds top-level JSON value was not an array")
        refund_keys = {"order_seq", "amount_cents"}
        for index, refund in enumerate(refunds):
            if type(refund) is not dict:
                raise ValueError(f"GET /refunds item {index} was not an object")
            if set(refund.keys()) != refund_keys:
                raise ValueError(f"GET /refunds item {index} did not contain exactly order_seq and amount_cents")
            if type(refund["order_seq"]) is not int:
                raise ValueError(f"GET /refunds item {index} order_seq was not a JSON integer")
            if type(refund["amount_cents"]) is not int:
                raise ValueError(f"GET /refunds item {index} amount_cents was not a JSON integer")
            if not batch_start_seq <= refund["order_seq"] <= batch_end_seq:
                raise ValueError(f"GET /refunds item {index} order_seq was outside the requested batch range")

        total_refunded_cents = sum(refund["amount_cents"] for refund in refunds)
        independently_recomputed_refunds = 0
        for refund in refunds:
            independently_recomputed_refunds += refund["amount_cents"]
        if total_refunded_cents != independently_recomputed_refunds:
            raise ValueError("refund sum differed from independent direct recomputation")
        if type(total_refunded_cents) is not int:
            raise ValueError("total_refunded_cents was not a JSON integer")

        payload = dict(baseline_payload)
        payload["total_refunded_cents"] = total_refunded_cents
        recomputed = dict(recomputed_baseline)
        recomputed["total_refunded_cents"] = independently_recomputed_refunds
        if set(payload.keys()) != final_batch_keys or set(recomputed.keys()) != final_batch_keys:
            raise ValueError("final batch output keys differed from the required six-key schema")
        if payload != recomputed:
            raise ValueError("final batch values differed from direct recomputation")
        if any(type(value) is not int for value in payload.values()):
            raise ValueError("one or more final batch values was not a JSON integer")
        log.info("PHASE independent recomputation matched all six output values")
    except Exception as exc:
        return deliver_hold(str(exc))

    try:
        batch_status = post_local_orders_json_once("/batches", payload)
    except Exception as exc:
        return deliver_hold(
            f"POST /batches delivery was unconfirmed due to {type(exc).__name__}; it was not retried"
        )
    if not 200 <= batch_status <= 299:
        return deliver_hold(
            f"POST /batches returned non-success HTTP status {batch_status}; it was not retried"
        )
    log.info("PHASE POST /batches confirmed successful http_status=%s", batch_status)
    return {"outcome": "delivered", "batch": payload, "batch_status": batch_status}

