def post_local_orders_json_once(path: str, payload: dict[str, object]) -> int:
    """Make exactly one bounded JSON POST to an allowed local orders endpoint and return its HTTP status. See guidance `Strict local orders batch delivery and HOLD protocol`."""
    import http.client
    import json
    import logging

    batch_keys = {
        "batch_start_seq",
        "batch_end_seq",
        "order_count",
        "total_units",
        "total_revenue_cents",
        "total_refunded_cents",
    }
    if path == "/batches":
        if set(payload.keys()) != batch_keys or any(type(value) is not int for value in payload.values()):
            raise ValueError("batch POST payload was not exactly the required six-integer object")
    elif path == "/owner/notify":
        if set(payload.keys()) != {"message"} or type(payload["message"]) is not str:
            raise ValueError("HOLD notification payload was not exactly a one-string-key object")
        if not payload["message"].startswith("HOLD: "):
            raise ValueError("owner notification message did not start with HOLD")
    else:
        raise ValueError("POST path was not an allowed local orders endpoint")

    body = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    headers = {"Content-Type": "application/json", "Content-Length": str(len(body))}
    logging.getLogger(__name__).info("PHASE posting %s exactly once", path)
    connection = http.client.HTTPConnection("127.0.0.1", 18184, timeout=5.0)
    try:
        connection.request("POST", path, body=body, headers=headers)
        response = connection.getresponse()
        return response.status
    finally:
        connection.close()

validate_and_compute_local_orders_page.implementation:
def validate_and_compute_local_orders_page(last_seq: int, orders: object) -> dict[str, object]:
    """Validate one orders page and return either the empty outcome or the unchanged five existing batch fields, before refunds are added by the runner. See guidance `Strict local orders batch delivery and HOLD protocol`."""
    import logging
    import re
    from datetime import date as Date

    log = logging.getLogger(__name__)
    order_keys = {"seq", "date", "region", "units", "unit_price_cents"}
    batch_keys = {
        "batch_start_seq",
        "batch_end_seq",
        "order_count",
        "total_units",
        "total_revenue_cents",
    }
    date_re = re.compile(r"\d{4}-\d{2}-\d{2}\Z")

    if type(last_seq) is not int or last_seq < 0:
        raise ValueError("validated last_seq input was not a non-negative JSON integer")
    if type(orders) is not list:
        raise ValueError("GET /orders top-level JSON value was not an array")
    if len(orders) > 200:
        raise ValueError(f"GET /orders returned {len(orders)} items, exceeding the 200-item limit")

    previous_seq = None
    seen_seqs = set()
    for index, order in enumerate(orders):
        if type(order) is not dict:
            raise ValueError(f"GET /orders item {index} was not an object")
        if set(order.keys()) != order_keys:
            raise ValueError(f"GET /orders item {index} did not contain exactly the required five keys")
        for field in ("seq", "units", "unit_price_cents"):
            if type(order[field]) is not int:
                raise ValueError(f"GET /orders item {index} field {field} was not a JSON integer")
        seq = order["seq"]
        if seq <= last_seq:
            raise ValueError(f"GET /orders item {index} seq was not greater than last_seq")
        if seq in seen_seqs:
            raise ValueError(f"GET /orders item {index} repeated a seq value")
        if previous_seq is not None and seq <= previous_seq:
            raise ValueError(f"GET /orders item {index} seq was not strictly increasing")
        seen_seqs.add(seq)
        previous_seq = seq

        if type(order["date"]) is not str:
            raise ValueError(f"GET /orders item {index} date was not a string")
        date_text = order["date"]
        if date_re.fullmatch(date_text) is None:
            raise ValueError(f"GET /orders item {index} date was not in exact YYYY-MM-DD format")
        try:
            parsed_date = Date.fromisoformat(date_text)
        except ValueError as exc:
            raise ValueError(f"GET /orders item {index} date was not a real calendar date") from exc
        if parsed_date.isoformat() != date_text:
            raise ValueError(f"GET /orders item {index} date was not canonical YYYY-MM-DD")
        if type(order["region"]) is not str:
            raise ValueError(f"GET /orders item {index} region was not a string")

    log.info("PHASE validated one orders page count=%s", len(orders))
    if not orders:
        log.info("SKIP empty orders page; no refunds GET and no batch POST are permitted")
        return {"outcome": "success_no_orders", "last_seq": last_seq, "order_count": 0}

    total_units = 0
    total_revenue_cents = 0
    order_count = 0
    for order in orders:
        order_count += 1
        total_units += order["units"]
        total_revenue_cents += order["units"] * order["unit_price_cents"]
    payload = {
        "batch_start_seq": orders[0]["seq"],
        "batch_end_seq": orders[-1]["seq"],
        "order_count": order_count,
        "total_units": total_units,
        "total_revenue_cents": total_revenue_cents,
    }
    recomputed = {
        "batch_start_seq": orders[0]["seq"],
        "batch_end_seq": orders[len(orders) - 1]["seq"],
        "order_count": sum(1 for _ in orders),
        "total_units": sum([order["units"] for order in orders]),
        "total_revenue_cents": sum(
            [order["units"] * order["unit_price_cents"] for order in orders]
        ),
    }
    if set(payload.keys()) != batch_keys or set(recomputed.keys()) != batch_keys:
        raise ValueError("candidate baseline batch keys differed from the required existing five-key schema")
    if payload != recomputed:
        raise ValueError("candidate baseline batch values did not equal independent direct recomputation")
    if any(type(value) is not int for value in payload.values()):
        raise ValueError("one or more candidate baseline batch values was not a JSON integer")
    log.info("PHASE independent recomputation matched all five existing output values")
    return {"outcome": "ready", "last_seq": last_seq, "batch": payload}

validate_local_orders_cursor.implementation:
def validate_local_orders_cursor(cursor: object) -> int:
    """Return the non-negative JSON integer in an object containing exactly `last_seq`. See guidance `Strict local orders batch delivery and HOLD protocol`."""
    if type(cursor) is not dict:
        raise ValueError("GET /batches/last top-level JSON value was not an object")
    if set(cursor.keys()) != {"last_seq"}:
        raise ValueError("GET /batches/last object did not contain exactly the required last_seq key")
    last_seq = cursor["last_seq"]
    if type(last_seq) is not int:
        raise ValueError("GET /batches/last last_seq was not a JSON integer")
    if last_seq < 0:
        raise ValueError("GET /batches/last last_seq was negative")
    return last_seq
